css:
& { padding:70px 100px; display:block; }
header { height:160px; }
header p { color:var(--accent); font:22px var(--font-mono); margin:0 0 18px; }
header h2 { font-size:58px; line-height:1.08; margin:0; max-width:42ch; text-wrap:balance; }
header :empty { display:none; }
.rib-stage { position:relative; height:760px; }
figure { position:absolute; inset:0; margin:0; }
figure img { width:100%; height:625px; object-fit:contain; border-radius:20px; }
figcaption { position:absolute; left:10px; right:10px; top:650px; display:flex; align-items:baseline; gap:30px; font-size:29px; line-height:1.25; }
figcaption b { color:var(--accent); min-width:230px; max-width:500px; }
figcaption span { max-width:1150px; }
.image-step { visibility:hidden; opacity:0!important; transition:opacity .25s ease; }
.image-step.in,.image-step:not([data-step]) { visibility:inherit; opacity:1!important; }
.image-step:has(~.image-step.in),.image-step:not([data-step]):has(~.image-step),.rib-base:has(~.image-step.in),.rib-base:has(~.image-step:not([data-step])) { visibility:hidden; opacity:0!important; }
&[data-body-motion="none"] * { transition:none!important; }
@media(prefers-reduced-motion:reduce) { & * { transition:none!important; } }
